class Solution {
public:
    long long maxPoints(vector<vector<int>>& points) {
        int m = points.size(), n = points[0].size();
        vector<long long> dp(points[0].begin(), points[0].end());

        for (int r = 1; r < m; r++) {
            vector<long long> left(n), right(n);
            left[0] = dp[0];
            for (int c = 1; c < n; c++) left[c] = max(left[c - 1] - 1, dp[c]);
            right[n - 1] = dp[n - 1];
            for (int c = n - 2; c >= 0; c--) right[c] = max(right[c + 1] - 1, dp[c]);

            vector<long long> newDp(n);
            for (int c = 0; c < n; c++) newDp[c] = points[r][c] + max(left[c], right[c]);
            dp = newDp;
        }
        long long ans = 0;
        for (long long x : dp) ans = max(ans, x);
        return ans;
    }
};

class Solution {
    public long maxPoints(int[][] points) {
        int m = points.length, n = points[0].length;
        long[] dp = new long[n];
        for (int c = 0; c < n; c++) dp[c] = points[0][c];

        for (int r = 1; r < m; r++) {
            long[] left = new long[n];
            long[] right = new long[n];
            left[0] = dp[0];
            for (int c = 1; c < n; c++) left[c] = Math.max(left[c - 1] - 1, dp[c]);
            right[n - 1] = dp[n - 1];
            for (int c = n - 2; c >= 0; c--) right[c] = Math.max(right[c + 1] - 1, dp[c]);

            long[] newDp = new long[n];
            for (int c = 0; c < n; c++) newDp[c] = points[r][c] + Math.max(left[c], right[c]);
            dp = newDp;
        }
        long ans = 0;
        for (long x : dp) ans = Math.max(ans, x);
        return ans;
    }
}

var maxPoints = function(points) {
  const m = points.length, n = points[0].length;
  let dp = points[0].map(Number);

  for (let r = 1; r < m; r++) {
    const left = new Array(n);
    const right = new Array(n);
    left[0] = dp[0];
    for (let c = 1; c < n; c++) left[c] = Math.max(left[c - 1] - 1, dp[c]);
    right[n - 1] = dp[n - 1];
    for (let c = n - 2; c >= 0; c--) right[c] = Math.max(right[c + 1] - 1, dp[c]);

    const newDp = new Array(n);
    for (let c = 0; c < n; c++) newDp[c] = points[r][c] + Math.max(left[c], right[c]);
    dp = newDp;
  }
  return Math.max(...dp);
};
